// ============================================================================
//  ota.h — over-the-air firmware update with a server-issued key
//
//  The device runs a small web updater while it is connected to the network:
//
//      POST http://<device-ip>:3232/update?key=<ota_token>   (multipart, .bin)
//
//  Security model
//  --------------
//  * `ota_token` is generated by the server (per device) and pushed to the
//    device through the normal config channel. An update is refused unless the
//    token matches, so a random host on the LAN cannot reflash the node.
//  * The token lives in NVS; wiping the device config (serial `reset`) clears
//    it, which also disables remote updates until the server provisions it
//    again.
//  * The updater only accepts a valid ESP32 image (Update.h validates the
//    magic byte and the size), and it runs on its own port so it never
//    interferes with the ranging loop.
//
//  A token in the query string is not ideal (it can land in logs), but it
//  keeps the device side tiny and works with plain `curl -F`. Use a trusted
//  LAN or a TLS reverse proxy in front of it.
// ============================================================================
#pragma once

#include <Arduino.h>
#include <WebServer.h>
#include <Update.h>
#include <WiFi.h>
#include "config.h"
#include "net.h"

extern WebServer g_ota;   // defined in main.cpp

// ---------------------------------------------------------------------------
// upload handling
// ---------------------------------------------------------------------------
inline void otaUploadStart()
{
    HTTPUpload &up = g_ota.upload();

    // authenticate before a single byte of the image is written
    const bool ok = cfg.ota_token[0] &&
                    g_ota.hasArg("key") &&
                    g_ota.arg("key") == cfg.ota_token;

    if (up.status == UPLOAD_FILE_START) {
        if (!ok) {
            Serial.println(F("[ota] rejected: bad or missing key"));
            return;
        }
        Serial.printf("[ota] receiving %s (%u bytes)\n",
                      up.filename.c_str(), (unsigned)up.totalSize);
        if (!Update.begin(UPDATE_SIZE_UNKNOWN)) {
            Serial.printf("[ota] Update.begin failed: %s\n", Update.errorString());
        }
    } else if (up.status == UPLOAD_FILE_WRITE) {
        if (!ok) return;
        if (Update.write(up.buf, up.currentSize) != up.currentSize)
            Serial.printf("[ota] write failed: %s\n", Update.errorString());
    } else if (up.status == UPLOAD_FILE_END) {
        if (!ok) return;
        if (Update.end(true)) {
            Serial.printf("[ota] success, %u bytes — rebooting\n", (unsigned)up.totalSize);
        } else {
            Serial.printf("[ota] Update.end failed: %s\n", Update.errorString());
        }
    } else if (up.status == UPLOAD_FILE_ABORTED) {
        Update.abort();
        Serial.println(F("[ota] aborted"));
    }
}

inline void otaRegister()
{
    g_ota.on("/update", HTTP_POST,
        // completion handler
        []() {
            const bool ok = Update.hasError() == false;
            g_ota.sendHeader("Connection", "close");
            g_ota.send(ok ? 200 : 500, "text/plain",
                       ok ? "OK: rebooting" : "FAILED");
            if (ok) { delay(300); ESP.restart(); }
        },
        otaUploadStart);

    // tiny status page so the device is discoverable on the LAN
    g_ota.on("/", HTTP_GET, []() {
        char id[16], eui[40];
        deviceId(cfg, id, sizeof(id));
        deviceEui(cfg, eui, sizeof(eui));
        char page[420];
        snprintf(page, sizeof(page),
                 "<!doctype html><meta name=viewport content='width=device-width,initial-scale=1'>"
                 "<body style=\"font:14px system-ui;background:#0b0e1a;color:#e8ecf8;padding:20px\">"
                 "<h2>UWB node</h2><p><b>%s</b><br>EUI <code>%s</code><br>firmware %s</p>"
                 "<p>IP %s &middot; RSSI %d dBm</p>"
                 "<p>OTA: %s</p>"
                 "<form method=post action='/update' enctype='multipart/form-data'>"
                 "<input type=file name=firmware required> "
                 "<input name=key placeholder='server key' required> "
                 "<button>Upload</button></form></body>",
                 id, eui, FW_VERSION,
                 WiFi.localIP().toString().c_str(), (int)WiFi.RSSI(),
                 cfg.ota_enabled ? "enabled" : "disabled");
        g_ota.send(200, "text/html", page);
    });
}

// ---------------------------------------------------------------------------
// lifecycle
// ---------------------------------------------------------------------------

// Start the updater once WiFi is up. Safe to call repeatedly.
inline void otaBegin()
{
    if (!cfg.ota_enabled || !net.wifi_up) return;
    static bool started = false;
    if (started) return;
    otaRegister();
    g_ota.begin(cfg.ota_port);
    started = true;
    Serial.printf("[ota] updater on http://%s:%u/update (key required)\n",
                  WiFi.localIP().toString().c_str(), (unsigned)cfg.ota_port);
}

inline void otaLoop()
{
    if (cfg.ota_enabled && net.wifi_up) g_ota.handleClient();
}
